 std::vector<std::string>trace;std::vector<uint32_t>collected;bool space=true,reject=false;FieldPresentHost h;h.admit_ready=[](auto&,std::string&){return true;};h.admit_interaction=[&](auto&,std::string&e){if(reject){e="source programme pending";return false;}return true;};h.read_flag=[&](const auto&b,bool&out,std::string&){out=std::find(collected.begin(),collected.end(),b.id)!=collected.end();return true;};h.write_flag=[&](const auto&b,bool value,std::string&){trace.push_back(value?"flag+":"flag-");collected.erase(std::remove(collected.begin(),collected.end(),b.id),collected.end());if(value)collected.push_back(b.id);return true;};h.inventory_space=[&](bool&out,std::string&){trace.push_back("space");out=space;return true;};h.select_item=[&](const auto&i,bool give,std::string&){assert(i.doses>0);trace.push_back(give?"give":"context");return true;};h.prompt_enabled=[](uint32_t,bool,std::string&){return true;};h.sound=[&](uint32_t,bool on,std::string&){trace.push_back(on?"sound+":"sound-");return true;};h.dialogue=[&](std::string_view path,std::string&){trace.push_back(std::string(path));return true;};FieldPresentRuntime r;assert(r.initialize(data,h,e));SourceRandom random(13);auto reference=random;
