 auto retained=*r.state(full.id);reject=true;assert(!r.interact(full.id,e)&&r.state(full.id)->animation_time==retained.animation_time&&r.state(full.id)->revert_waiters.empty());reject=false;assert(r.interact(full.id,e)&&r.exit_tree(full.id,e)&&r.state(full.id)->revert_waiters.empty()&&!r.state(full.id)->alive);assert(!r.interact(full.id,e));assert(!r.idle_frame(std::numeric_limits<double>::quiet_NaN(),true,e));assert(!r.idle_frame(-1,true,e));assert(!r.idle_frame(.2,true,e));
 // Saved collected flag still consumes the child's shared draw, then hides it.
 FieldPresentRuntime saved;assert(saved.initialize(data,h,e));auto before=random;assert(saved.ready_sparkles(b.sparkles_id,random,e)&&random.state()!=before.state());assert(saved.ready_present(b.id,e)&&saved.state(b.id)->frame==b.opened_frame&&!saved.state(b.id)->sparkle_playing);assert(!FieldPresentRuntime{}.initialize(data,{},e));
 std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(f)),{});auto recalc=[](std::vector<uint8_t>&b){uint32_t crc=~0u;for(size_t i=0;i<b.size();++i){crc^=i>=16&&i<20?0:b[i];for(unsigned j=0;j<8;++j)crc=(crc>>1)^(0xedb88320u&uint32_t(-int32_t(crc&1)));}crc=~crc;for(unsigned i=0;i<4;++i)b[16+i]=uint8_t(crc>>(i*8));};for(unsigned at:{8u,20u,24u}){auto malformed=bytes;malformed[at]=99;recalc(malformed);assert(!data.load(malformed.data(),malformed.size(),e)&&data.valid());}auto malformed=bytes;malformed.back()^=1;assert(!data.load(malformed.data(),malformed.size(),e));assert(!data.load(nullptr,0,e));
